"""Descriptive fixed-final N4 capacity-order report after independent verification."""
import argparse,csv,hashlib,json,shutil
from pathlib import Path
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import numpy as np

CORE=('capacity_order_ppo','fixed_order_ppo','reverse_capacity_ppo','mask_only_order_ppo','independent_machine_q_ppo','independent_machine_p_ppo');ARMS=(*CORE,'raw_tech_ppo','ppo','normalized_ppo','mappo','full_mappo');LABELS=('Capacity order','Fixed ID order','Reverse capacity','Mask only','Independent physical q','Independent proposal p','Raw technician order','PPO','PPO normalized','MAPPO local','MAPPO full');NAMES=dict(zip(ARMS,LABELS))
def read(p):return json.loads(p.read_text())
def sha(p):
    h=hashlib.sha256()
    with p.open('rb') as f:
        for b in iter(lambda:f.read(4*1024*1024),b''):h.update(b)
    return h.hexdigest()
def rows(p):
    with p.open() as f:return list(csv.DictReader(f))


def run(source,verification,output):
    source=Path(source).resolve();verification=Path(verification).resolve();out=Path(output).resolve();out.mkdir(parents=True,exist_ok=False);sm=read(source/'manifest.json');vm=read(verification/'manifest.json');v=read(verification/'verification.json');s=read(source/'summary.json');assert sm['status']=='COMPLETED' and sm['audit_status']=='PASS' and vm['status']=='COMPLETED' and v['status']=='PASS' and v['source']==str(source) and v['source_manifest_sha256']==sha(source/'manifest.json') and v['independent_checks']==s['checks'] and v['original_development_pass']==s['development_screen_pass'] and not s['test_opened']
    for root,entries in ((source,sm['output_bindings']),(verification,vm['outputs'])):
        for name,meta in entries.items():assert sha(root/name)==meta['sha256'],name
    dev=rows(source/'development_episodes.csv');selected=rows(source/'selected_episodes.csv');trains=sorted({int(r['train_seed']) for r in dev});steps=sorted({int(r['checkpoint_steps']) for r in dev});curves=[];replicas={};conflicts={};components={}
    for a in ARMS:
        replicas[a]={str(t):float(np.mean([float(r['normalized_cost']) for r in selected if r['method']==a and int(r['train_seed'])==t])) for t in trains};conflicts[a]={k:float(np.mean([float(r[k]) for r in selected if r['method']==a])) for k in ('broker_conflicts','broker_rejected_proposals')};components[a]={k:float(np.mean([float(r[k])/4 for r in selected if r['method']==a])) for k in ('maintenance_cost','unavailability_cost','failure_cost','waiting_cost')}
        for step in steps:curves.append(dict(method=a,steps=step,normalized_cost=float(np.mean([float(r['normalized_cost']) for r in dev if r['method']==a and int(r['checkpoint_steps'])==step]))))
    duration=np.array(read(source/'physics.json')['service_time']);opportunities=dict(decisions=0,multiple_active_with_free_worker=0,capacity_order_differs_from_active_ID_order=0,active_machine_histogram=[0]*5,free_worker_histogram=[0]*3)
    with (source/'decisions.csv').open() as f:
        for row in csv.DictReader(f):
            if row['method']!=CORE[0] or int(row['tick'])>=48:continue
            state=json.loads(row['state']);free=[j for j,r in enumerate(state['remaining']) if r==0];serving={m for m in state['assigned'] if m>=0};active=[m for m in range(4) if free and m not in serving and (state['failed'][m] or state['ages'][m]>=3)];capacity_order=sorted(active,key=lambda m:(sum(1/duration[m,j] for j in free),m));opportunities['decisions']+=1;opportunities['multiple_active_with_free_worker']+=int(len(active)>=2);opportunities['capacity_order_differs_from_active_ID_order']+=int(capacity_order!=active);opportunities['active_machine_histogram'][len(active)]+=1;opportunities['free_worker_histogram'][len(free)]+=1
    assert opportunities['decisions']==4608;data=dict(classification='DESCRIPTIVE_CAPACITY_ORDER_DEV_ONLY',summary=s,curves=curves,replica_costs=replicas,policy_conflicts=conflicts,cost_components_per_machine=components,candidate_order_descriptors=opportunities,source=str(source),verification=str(verification),goal_pass=False,test_opened=False,limitation='Fixed final checkpoint; three DEV replicas, dots/lines are not confidence intervals. Order opportunity/conflict descriptors do not establish causal benefit.')
    (out/'analysis.json').write_text(json.dumps(data,indent=2));fig,axes=plt.subplots(1,3,figsize=(16,5.5),layout='constrained');y=np.arange(11);axes[0].barh(y,[s['means'][a]['normalized_cost'] for a in ARMS],color=['#1565C0']+['#B0BEC5']*10)
    for j,t in enumerate(trains):axes[0].scatter([replicas[a][str(t)] for a in ARMS],y+(j-1)*.12,color=['#212121','#E65100','#6A1B9A'][j],s=12,label=f'Replica {j+1}',zorder=3)
    axes[0].set_yticks(y,LABELS);axes[0].invert_yaxis();axes[0].set_xlabel('Mean H60 cost / machine');axes[0].set_title('Fixed final 491520; dots = replica means');axes[0].legend(fontsize=7)
    gains=[100*s['endpoints']['gain_vs_'+a] for a in ARMS[1:]];bounds=[.5 if a in ('fixed_order_ppo','independent_machine_q_ppo') else 0 if a in ('mappo','full_mappo') else -1 for a in ARMS[1:]];axes[1].barh(np.arange(10),gains,color=['#2E7D32' if s['checks']['gain_vs_'+a] else '#C62828' for a in ARMS[1:]]);axes[1].scatter(bounds,np.arange(10),color='black',marker='|',s=150,label='Locked bound');axes[1].set_yticks(np.arange(10),LABELS[1:]);axes[1].invert_yaxis();axes[1].axvline(0,color='gray',lw=.7);axes[1].set_xlabel('Candidate cost gain vs control (%)');axes[1].set_title('10 cost gates: green pass, red fail');axes[1].legend(fontsize=7)
    health=[];labels=[];colors=[]
    for a in ('ppo','normalized_ppo'):
        for metric,limit in (('availability',-.01),('normalized_pending',.025),('normalized_failures',.25)):
            key=metric+'_delta_vs_'+a;health.append(s['endpoints'][key]/limit);labels.append({'availability':'Avail','normalized_pending':'Pending','normalized_failures':'Failures'}[metric]+' / '+NAMES[a]);colors.append('#2E7D32' if s['checks'][key] else '#C62828')
    axes[2].barh(np.arange(6),health,color=colors);axes[2].set_yticks(np.arange(6),labels);axes[2].invert_yaxis();axes[2].axvline(1,color='black',ls='--',label='Maximum harm');axes[2].axvline(0,color='gray',lw=.7);axes[2].set_xlabel('Health harm / locked allowance');axes[2].set_title('6 health gates; lower is better');axes[2].legend(fontsize=7);fig.suptitle('Capacity-priority machine-agent PPO DEV — descriptive, no confidence intervals');fig.savefig(out/'quality_health.png',dpi=170);plt.close(fig)
    fig,axes=plt.subplots(1,3,figsize=(15,4.8),layout='constrained');colors=plt.cm.tab10(np.arange(8));focus=(*CORE[:5],'raw_tech_ppo','ppo','normalized_ppo')
    for a,color in zip(focus,colors):axes[0].plot(np.array(steps)/1000,[r['normalized_cost'] for r in curves if r['method']==a],label=NAMES[a],color=color,marker='.',lw=1.2)
    axes[0].set_xlabel('Training decisions (thousands)');axes[0].set_ylabel('Mean DEV H60 cost / machine');axes[0].set_title('All registered checkpoints');axes[0].legend(fontsize=6.5,ncol=2)
    per=[100*s['per_replica_main_gain'][str(t)] for t in trains];axes[1].bar(np.arange(3),per,color=['#2E7D32' if g>0 else '#C62828' for g in per]);axes[1].axhline(0,color='black',lw=.7);axes[1].axhline(.5,color='gray',ls='--',label='Pooled bound 0.5%');axes[1].set_xticks(np.arange(3),['Replica1','Replica2','Replica3']);axes[1].set_ylabel('Cost gain vs fixed ID order (%)');axes[1].set_title('Additional guard: each replica >0');axes[1].legend(fontsize=7)
    axes[2].barh(np.arange(6),[conflicts[a]['broker_rejected_proposals'] for a in CORE],color=['#1565C0']+['#B0BEC5']*5);axes[2].set_yticks(np.arange(6),LABELS[:6]);axes[2].invert_yaxis();axes[2].set_xlabel('Rejected proposals / policy episode');axes[2].set_title('Collision count alone is not performance');fig.suptitle('Learning and coordination — trained ablation cost determines mechanism support');fig.savefig(out/'learning_coordination.png',dpi=170);plt.close(fig)
    passed=sum(s['checks'].values());failed=[k for k,ok in s['checks'].items() if not ok];extra=[k for k,ok in s['extra_checks'].items() if not ok];verdict='ĐẠT DEV; cần confirmation riêng trước kết luận khoa học' if s['development_screen_pass'] else 'KHÔNG ĐẠT DEV; giữ kết quả âm và chưa mở confirmation/test';lines=['# Capacity-priority machine-agent PPO v1: kết quả N4/K2','',f'**{verdict}.** {passed}/16 tiêu chí điểm đạt; mục tiêu nghiên cứu tổng thể chưa đạt.','',
    '## Giả thuyết và phương pháp','',
    'Cho máy ít lựa chọn phục vụ nhanh chọn technician trước có thể giữ cơ hội cho máy khó phục vụ; các máy sau nhìn reservation thật để chọn hoặc WAIT. Xếp máy đang có cạnh hợp lệ theo c_m=Σ_j 1/D_mj tăng dần, tie ID; thứ tự tính từ trạng thái hiện tại một lần mỗi tick. Máy không active đi cuối. Thứ tự không được coi là tối ưu; policy có thể WAIT và để máy sau được phục vụ. Mọi service start thực thi đồng thời.','',
    'Actor raw104→64→64→3 dùng chung giữa bốn máy, nhận đầy đủ state71 cùng own-machine/edges/plan/reserved/processed/ID/position. Mỗi máy chọn WAIT hoặc technician chưa được giữ chỗ. Canonical vector theo machine ID có một trace cho mỗi matching; scalar joint PPO dùng tổng log conditionals. Critic chỉ nhận state và không chạy khi select. Có19.908 tham số ở mỗi nhánh lõi, cùng tensor khởi tạo riêng và cùng sensing/budget.','',
    'Head actor cuối khởi tạo0; prior đếm completion matching bằng log DP C(n,k)=C(n−1,k)+kC(n−1,k−1). Nhờ đó mỗi matching khả thi ở bốn nhánh phối hợp có cùng xác suất ban đầu,1/21 khi đủ N4/K2. Chỉ áp dụng complete-bipartite active/free support của benchmark; không tuyên bố cho arbitrary skill masks. Actor/decoder/core observation không liệt kê matching. Việc đếm21/81 chỉ dùng trong reference độc lập.','',
    'Các ablation là fixed ID order, reverse capacity, mask-only input, independent machine physical-q và independent proposal-p. Independent requests chỉ nhìn trạng thái gốc, broker chọn R/D cao nhất trên từng technician, người thua WAIT. Hai density modes đều báo cáo. Nhánh độc lập có phân phối matching ban đầu khác do bỏ phối hợp; không diễn giải gain này thành riêng lợi ích học message. Baseline thêm raw technician-first và PPO/MAPPO với khác biệt architecture/capacity được công bố trong protocol.','',
    'Giữ PPO scalar joint, MC/state advantage chuẩn hóa chung, Adam3e−4, clip0.2, entropy0.01, global clip0.5 và reward−cost/20. Toàn bộ mô hình học từ random initialization, không teacher/labels/distillation/warm-start. Generic autoregression/variable ordering/de-biasing đã có prior art: [allocation NeurIPS2024](https://arxiv.org/abs/2409.18735), [PARCO NeurIPS2025](https://arxiv.org/abs/2409.03811), [MRV](https://aima.cs.berkeley.edu/4th-ed/pdfs/newchap05.pdf). Chưa tuyên bố mới ở các ý tưởng chung đó.','',
    '## Thiết kế đã khóa','',
    '33 fits, ba training seeds mới ×11 phương pháp,491.520 quyết định/fit; tổng16.220.160 quyết định,337.920 train episodes và253.440 Adam updates.32 DEV seeds, năm checkpoint gồm bước0. PRIMARY dùng cố định491.520; không thay bằng checkpoint/seed tốt nhất. H48 policy và12tail chung; health tại cutoff48. Không scientific test hay N lớn ở vòng này.','',
    '## Kết quả fixed final','', '| Nhánh | Cost/máy H60 | Availability H48 | Pending/máy H48 | Failure/máy H48 |','|---|---:|---:|---:|---:|']
    for a in ARMS:
        m=s['means'][a];lines.append(f"| {NAMES[a]} | {m['normalized_cost']:.6f} | {m['availability']:.6f} | {m['normalized_pending']:.6f} | {m['normalized_failures']:.6f} |")
    lines+=['','| Tiêu chí | Giá trị điểm | Đạt |','|---|---:|---|']
    for k,value in s['endpoints'].items():lines.append(f"| {k} | {value:.8f} | {'Có' if s['checks'][k] else 'Không'} |")
    lines+=['',f"Gain vs fixed order từng seed: {', '.join(f'{t}: {g:.4f}%' for t,g in zip(trains,per))}.",f"P95 actor+decoder: {s['latency']['p95_ms']:.6f}ms,432 mẫu khi pool đã đóng; chỉ chứng minh latency ở N4 trên lab.",f"Không đạt: {', '.join(failed) or 'không'}. Extra không đạt: {', '.join(extra) or 'không'}.",'',
    '## Bằng chứng cơ chế và giới hạn','',
    f"Trong4.608 quyết định greedy candidate, có {opportunities['multiple_active_with_free_worker']} trạng thái có ít nhất hai máy active và worker rảnh; thứ tự active capacity khác ID ở {opportunities['capacity_order_differs_from_active_ID_order']} trạng thái. Đây là mô tả cơ hội thay thứ tự trên trajectory candidate, không phải nhãn tối ưu hay bằng chứng giảm cost.",'',
    'Ablation huấn luyện cùng thông tin/dung lượng/ngân sách mới là bằng chứng chính. Không lấy zero conflict, order đổi hoặc prior đúng làm kết luận thuật toán tốt. Lợi ích so local MAPPO ít thông tin hơn cũng không thay cho đối chứng chính/full MAPPO. Nếu thiếu bất kỳ gate, giữ nguyên verdict và không tự động đổi order formula/LR/prior/budget để cứu.','',
    'Kiểm chứng độc lập dựng33 bộ tensor khởi tạo, seed roles/tapes/budgets/fixed endpoint; replay1.088episode/65.280 primitive transitions/52.224policy decisions. NumPy dựng actor và đếm matching completions trực tiếp theo prefix, tách khỏi DP của production; independent q cộng đủ81latent proposals. Tính lại16gates và432raw timings. Các historical minibatch gradients không lưu đầy đủ, nên không tuyên bố replay từng optimizer update. Audit PASS xác nhận số liệu, không chứng minh CI, scalability hay goal completion.','',f'Nguồn: `{source}`.',f'Audit: `{verification}`.','', '![Chất lượng và sức khỏe](quality_health.png)','![Learning và phối hợp](learning_coordination.png)','']
    (out/'findings_vi.md').write_text('\n'.join(lines));shutil.copy2(__file__,out/'reporter.py');manifest=dict(status='COMPLETED',source_manifest_sha256=sha(source/'manifest.json'),verification_manifest_sha256=sha(verification/'manifest.json'),goal_pass=False,test_opened=False,outputs={p.name:dict(sha256=sha(p),bytes=p.stat().st_size) for p in out.iterdir() if p.is_file()});(out/'manifest.json').write_text(json.dumps(manifest,indent=2));print(out)

if __name__=='__main__':
    p=argparse.ArgumentParser(description=__doc__);p.add_argument('--source',required=True);p.add_argument('--verification',required=True);p.add_argument('--output',required=True);a=p.parse_args();run(a.source,a.verification,a.output)
